import { useCallback, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  analyzeCode,
  createDocument,
  deleteDocument,
  fetchDocument,
  fetchDocuments,
  updateDocument,
} from '../api';

function ComplexityGraph({ coordinates }) {
  if (!coordinates || coordinates.length === 0) {
    return null;
  }

  const padding = { top: 24, right: 24, bottom: 40, left: 52 };
  const width = 560;
  const height = 220;
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;

  const maxInput = Math.max(...coordinates.map((p) => p.input_size));
  const maxOps = Math.max(...coordinates.map((p) => p.operations));

  const scaleX = (inputSize) =>
    padding.left + (inputSize / maxInput) * chartWidth;
  const scaleY = (operations) =>
    padding.top + chartHeight - (operations / maxOps) * chartHeight;

  const points = coordinates
    .map((p) => `${scaleX(p.input_size)},${scaleY(p.operations)}`)
    .join(' ');

  const yTicks = [0, Math.round(maxOps / 2), maxOps];
  const xTicks = coordinates.map((p) => p.input_size);

  return (
    <div className="graph-container">
      <svg
        className="graph-svg"
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label="Operations vs input size chart"
      >
        <line
          x1={padding.left}
          y1={padding.top + chartHeight}
          x2={padding.left + chartWidth}
          y2={padding.top + chartHeight}
          stroke="#475569"
          strokeWidth="1"
        />
        <line
          x1={padding.left}
          y1={padding.top}
          x2={padding.left}
          y2={padding.top + chartHeight}
          stroke="#475569"
          strokeWidth="1"
        />
        {yTicks.map((tick) => (
          <g key={`y-${tick}`}>
            <line
              x1={padding.left}
              y1={scaleY(tick)}
              x2={padding.left + chartWidth}
              y2={scaleY(tick)}
              stroke="#334155"
              strokeWidth="1"
              strokeDasharray="4 4"
            />
            <text
              x={padding.left - 8}
              y={scaleY(tick) + 4}
              textAnchor="end"
              fill="#94a3b8"
              fontSize="10"
            >
              {tick}
            </text>
          </g>
        ))}
        {xTicks.map((tick) => (
          <text
            key={`x-${tick}`}
            x={scaleX(tick)}
            y={padding.top + chartHeight + 20}
            textAnchor="middle"
            fill="#94a3b8"
            fontSize="10"
          >
            {tick}
          </text>
        ))}
        <polyline
          points={points}
          fill="none"
          stroke="#38bdf8"
          strokeWidth="2.5"
          strokeLinejoin="round"
        />
        {coordinates.map((p) => (
          <circle
            key={p.input_size}
            cx={scaleX(p.input_size)}
            cy={scaleY(p.operations)}
            r="5"
            fill="#38bdf8"
            stroke="#0f172a"
            strokeWidth="2"
          />
        ))}
        <text
          x={padding.left + chartWidth / 2}
          y={height - 6}
          textAnchor="middle"
          fill="#94a3b8"
          fontSize="11"
        >
          Input size (n)
        </text>
        <text
          x={14}
          y={padding.top + chartHeight / 2}
          textAnchor="middle"
          fill="#94a3b8"
          fontSize="11"
          transform={`rotate(-90, 14, ${padding.top + chartHeight / 2})`}
        >
          Operations
        </text>
      </svg>
      <div className="graph-legend">
        <span>Blue line: estimated operations at each input size</span>
      </div>
    </div>
  );
}

function Dashboard() {
  const navigate = useNavigate();
  const [documents, setDocuments] = useState([]);
  const [selectedId, setSelectedId] = useState(null);
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [analysis, setAnalysis] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [error, setError] = useState('');
  const [status, setStatus] = useState('');

  const username = localStorage.getItem('algospace_username') || 'Developer';

  const loadDocuments = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const data = await fetchDocuments();
      const list = Array.isArray(data) ? data : [];
      setDocuments(list);
    } catch (err) {
      setError(err.message || 'Failed to load documents.');
      setDocuments([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadDocuments();
  }, [loadDocuments]);

  const selectDocument = async (id) => {
    setError('');
    setStatus('');
    setAnalysis(null);
    try {
      const doc = await fetchDocument(id);
      setSelectedId(doc.id);
      setTitle(doc.title);
      setContent(doc.content || '');
    } catch (err) {
      setError(err.message || 'Failed to load document.');
    }
  };

  const handleNewDocument = async () => {
    setError('');
    setStatus('');
    setAnalysis(null);
    try {
      const doc = await createDocument({
        title: 'Untitled',
        content: '',
      });
      await loadDocuments();
      setSelectedId(doc.id);
      setTitle(doc.title);
      setContent(doc.content || '');
      setStatus('New document created.');
    } catch (err) {
      setError(err.message || 'Failed to create document.');
    }
  };

  const handleSave = async () => {
    if (!selectedId) {
      setError('Select or create a document before saving.');
      return;
    }
    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      setError('Title cannot be empty.');
      return;
    }
    setSaving(true);
    setError('');
    setStatus('');
    try {
      await updateDocument(selectedId, {
        title: trimmedTitle,
        content,
        ...(analysis
          ? {
              time_complexity: analysis.time_complexity,
              space_complexity: analysis.space_complexity,
              justification: analysis.justification,
            }
          : {}),
      });
      await loadDocuments();
      setStatus('Document saved.');
    } catch (err) {
      setError(err.message || 'Failed to save document.');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!selectedId) {
      setError('No document selected to delete.');
      return;
    }
    setError('');
    setStatus('');
    try {
      await deleteDocument(selectedId);
      setSelectedId(null);
      setTitle('');
      setContent('');
      setAnalysis(null);
      await loadDocuments();
      setStatus('Document deleted.');
    } catch (err) {
      setError(err.message || 'Failed to delete document.');
    }
  };

  const handleAnalyze = async () => {
    const trimmed = content.trim();
    if (!trimmed) {
      setError('Cannot analyze empty code. Enter code in the editor first.');
      setAnalysis(null);
      return;
    }
    setAnalyzing(true);
    setError('');
    setStatus('');
    try {
      const result = await analyzeCode(trimmed);
      setAnalysis(result);
      setStatus('Complexity analysis complete.');
    } catch (err) {
      setAnalysis(null);
      setError(err.message || 'Analysis request failed.');
    } finally {
      setAnalyzing(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('algospace_token');
    localStorage.removeItem('algospace_username');
    navigate('/auth');
  };

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <h1>AlgoSpace</h1>
        <div className="dashboard-header-actions">
          <span className="user-info">Signed in as {username}</span>
          <button type="button" className="btn btn-danger" onClick={handleLogout}>
            Log out
          </button>
        </div>
      </header>

      <div className="dashboard-body">
        <aside className="sidebar">
          <div className="sidebar-header">
            <h2>Files</h2>
            <button type="button" className="btn btn-primary" onClick={handleNewDocument}>
              + New file
            </button>
          </div>
          {error && <div className="alert alert-error" style={{ margin: '0.5rem 1rem' }}>{error}</div>}
          <ul className="file-list">
            {loading && (
              <li className="empty-state">Loading documents...</li>
            )}
            {!loading && documents.length === 0 && (
              <li className="empty-state">No files yet. Create one to get started.</li>
            )}
            {!loading &&
              documents.map((doc) => (
                <li key={doc.id}>
                  <button
                    type="button"
                    className={selectedId === doc.id ? 'active' : ''}
                    onClick={() => selectDocument(doc.id)}
                  >
                    {doc.title || 'Untitled'}
                  </button>
                </li>
              ))}
          </ul>
        </aside>

        <main className="workspace">
          <div className="workspace-toolbar">
            <input
              type="text"
              className="title-input"
              placeholder="Document title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              disabled={!selectedId}
            />
            <button
              type="button"
              className="btn btn-secondary"
              onClick={handleSave}
              disabled={!selectedId || saving}
            >
              {saving ? 'Saving...' : 'Save'}
            </button>
            <button
              type="button"
              className="btn btn-primary"
              onClick={handleAnalyze}
              disabled={!selectedId || analyzing}
            >
              {analyzing ? 'Analyzing...' : 'Analyze Complexity'}
            </button>
            <button
              type="button"
              className="btn btn-danger"
              onClick={handleDelete}
              disabled={!selectedId}
            >
              Delete
            </button>
            {status && <span className="status-message">{status}</span>}
          </div>

          <div className="editor-area">
            <textarea
              placeholder="Write code or markdown here..."
              value={content}
              onChange={(e) => setContent(e.target.value)}
              disabled={!selectedId}
            />

            {analysis && (
              <section className="analysis-panel">
                <h3>Complexity Analysis</h3>
                <div className="complexity-meta">
                  <div>
                    <span>Time</span>
                    <strong>{analysis.time_complexity}</strong>
                  </div>
                  <div>
                    <span>Space</span>
                    <strong>{analysis.space_complexity}</strong>
                  </div>
                </div>
                <p className="justification-text">{analysis.justification}</p>
                <ComplexityGraph coordinates={analysis.graph_coordinates} />
              </section>
            )}
          </div>
        </main>
      </div>
    </div>
  );
}

export default Dashboard;
